typedef struct { struct err entries[32]; size_t count; } notification;

void check_seats(notification *n, const booking *b) {
    if (b->seats < 1 || b->seats > 20)
        note_add(n, ERR_SEATS_RANGE, "seats");
}

void check_date(notification *n, const booking *b) {
    if (b->date[0] == '\0') note_add(n, ERR_DATE_MISSING, "date");
}
